// Parse the shopping agent's structured JSON reply, falling back gracefully
const item = $input.item.json;
const raw = item.output || item.text || item.response || '{}';

let parsed = {};
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    replyText: String(raw),
    shortlist: [],
    purchaseIntent: false,
    selectedProductId: null,
    selectedProductName: '',
    selectedProductPrice: 0,
    quantity: 1
  };
}

const config = $('Set - Config').item.json;

return {
  json: {
    ...config,
    replyText: parsed.replyText || '',
    shortlist: parsed.shortlist || [],
    purchaseIntent: !!parsed.purchaseIntent,
    selectedProductId: parsed.selectedProductId || null,
    selectedProductName: parsed.selectedProductName || '',
    selectedProductPrice: parsed.selectedProductPrice || 0,
    quantity: parsed.quantity || 1
  }
};

// Turn the async order-confirmation callback into a clean notification
const webhookData = $input.item.json.body || $input.item.json;
const orderCtx = $('HTTP Request - Create Order (Checkout API)').item.json;
const cfg = $('JS - Parse Agent Output & Build Shortlist').item.json;

const orderId = webhookData.orderId || orderCtx.id || 'unknown';
const status = webhookData.status || orderCtx.status || 'pending';
const total = webhookData.total || (cfg.selectedProductPrice * cfg.quantity);
const currency = cfg.currency || 'USD';
const eta = webhookData.estimatedDelivery || 'TBD';

const message = 'Order ' + orderId + ' is ' + status + '. Total: ' + currency + ' ' + total + '. Estimated delivery: ' + eta + '. Item: ' + cfg.selectedProductName + ' x' + cfg.quantity + '.';

return {
  json: {
    ...cfg,
    orderId,
    orderStatus: status,
    orderTotal: total,
    orderCurrency: currency,
    estimatedDelivery: eta,
    notificationMessage: message
  }
};
